import{_ as s,C as n,o as t,c as o,a2 as a,b as l,w as i,a as d,E as c,a3 as m}from"./chunks/framework.Dd_iHz3e.js";const _=JSON.parse('{"title":"14.13 Real-Time Systems, Video Streaming & Media Pipelines","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/14.13-real-time-systems.md","filePath":"system-design/14.13-real-time-systems.md"}'),h={name:"system-design/14.13-real-time-systems.md"};function g(p,e,u,v,b,S){const r=n("Mermaid");return t(),o("div",null,[e[1]||(e[1]=a('<h1 id="_14-13-real-time-systems-video-streaming-media-pipelines" tabindex="-1">14.13 Real-Time Systems, Video Streaming &amp; Media Pipelines <a class="header-anchor" href="#_14-13-real-time-systems-video-streaming-media-pipelines" aria-label="Permalink to &quot;14.13 Real-Time Systems, Video Streaming &amp; Media Pipelines&quot;">​</a></h1><h2 id="_1-plain-english-overview" tabindex="-1">1. Plain English Overview <a class="header-anchor" href="#_1-plain-english-overview" aria-label="Permalink to &quot;1. Plain English Overview&quot;">​</a></h2><p>Real-time systems deliver live data, media streams, and collaborative updates with sub-second latency, enabling instant video playback, live culinary masterclasses, and real-time social engagement counters.</p><hr><h2 id="_2-usage-in-cooking-nexus" tabindex="-1">2. Usage in Cooking Nexus <a class="header-anchor" href="#_2-usage-in-cooking-nexus" aria-label="Permalink to &quot;2. Usage in Cooking Nexus&quot;">​</a></h2><ul><li><strong>Reel Video Player</strong>: Full-screen vertical video playback with optimistic UI interactions in [src/pages/ReelsFeed.tsx](file:///Users/avishjain/avishjain9-repos/26-cooking-nexus/27-kitchen-companion-pro/src/pages/ReelsFeed.tsx).</li><li><strong>Live Stream View</strong>: Interactive creator live stream broadcasting in [src/pages/LiveStreamPage.tsx](file:///Users/avishjain/avishjain9-repos/26-cooking-nexus/27-kitchen-companion-pro/src/pages/LiveStreamPage.tsx).</li><li><strong>AI Token Streaming</strong>: Server-Sent Events delivering streaming LLM output in [src/lib/ai-stream.ts](file:///Users/avishjain/avishjain9-repos/26-cooking-nexus/27-kitchen-companion-pro/src/lib/ai-stream.ts).</li></ul><hr><h2 id="_3-video-transcoding-hls-streaming-pipeline" tabindex="-1">3. Video Transcoding &amp; HLS Streaming Pipeline <a class="header-anchor" href="#_3-video-transcoding-hls-streaming-pipeline" aria-label="Permalink to &quot;3. Video Transcoding &amp; HLS Streaming Pipeline&quot;">​</a></h2>',8)),(t(),l(m,null,{default:i(()=>[c(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20Creator%5B%22Chef%20Uploads%20Raw%20MP4%20(UploaderDashboard)%22%5D%20--%3E%20S3Ingest%5B%22S3%20Raw%20Upload%20Bucket%22%5D%0A%20%20%20%20S3Ingest%20--%3E%20LambdaTrigger%5B%22AWS%20EventBridge%20%2F%20Lambda%22%5D%0A%20%20%20%20LambdaTrigger%20--%3E%20MediaConvert%5B%22AWS%20Elemental%20MediaConvert%20%2F%20FFmpeg%22%5D%0A%0A%20%20%20%20MediaConvert%20--%3E%7CTranscode%20to%20Multi-Bitrate%7C%20HLSOutput%5B%22HLS%20Streams%20(1080p%2C%20720p%2C%20480p)%22%5D%0A%20%20%20%20HLSOutput%20--%3E%20S3Deliver%5B%22S3%20Output%20Bucket%22%5D%0A%20%20%20%20S3Deliver%20--%3E%20CloudFront%5B%22AWS%20CloudFront%20CDN%22%5D%0A%20%20%20%20CloudFront%20--%3E%20MobileViewer%5B%22Mobile%20Cook%20(ReelsFeed.tsx)%22%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<hr><h2 id="_4-real-time-transport-protocols-comparison" tabindex="-1">4. Real-Time Transport Protocols Comparison <a class="header-anchor" href="#_4-real-time-transport-protocols-comparison" aria-label="Permalink to &quot;4. Real-Time Transport Protocols Comparison&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Protocol</th><th>Latency</th><th>Bandwidth Efficiency</th><th>Server Connection State</th><th>Scalability</th><th>Fit for Cooking Nexus</th></tr></thead><tbody><tr><td><strong>HLS / DASH (Chosen for Video)</strong></td><td>2 - 6 seconds</td><td>Extreme (Byte-range caching)</td><td>Stateless HTTP</td><td>Unlimited via Edge CDN</td><td>Optimal for 60-second culinary reels</td></tr><tr><td><strong>Server-Sent Events (SSE)</strong></td><td>&lt;250ms</td><td>High (No polling overhead)</td><td>Light state (HTTP stream)</td><td>High (Standard load balancers)</td><td>Optimal for AI Chat streaming</td></tr><tr><td><strong>WebSockets</strong></td><td>&lt;50ms</td><td>High</td><td>Heavy state (Persistent TCP)</td><td>Complex (Requires Redis pub/sub)</td><td>Optimal for live masterclass chat</td></tr><tr><td><strong>WebRTC</strong></td><td>&lt;200ms</td><td>High (Peer-to-peer / SFU)</td><td>Complex signaling</td><td>Challenging at 10k+ viewers</td><td>Optimal for 1-on-1 cooking coaching</td></tr><tr><td><strong>Short Polling</strong></td><td>1 - 5 seconds</td><td>Terrible (90% empty replies)</td><td>Stateless</td><td>Poor</td><td>Anti-pattern; avoid</td></tr></tbody></table><hr><h2 id="_5-live-stream-chat-architecture-redis-pub-sub" tabindex="-1">5. Live Stream Chat Architecture (Redis Pub/Sub) <a class="header-anchor" href="#_5-live-stream-chat-architecture-redis-pub-sub" aria-label="Permalink to &quot;5. Live Stream Chat Architecture (Redis Pub/Sub)&quot;">​</a></h2><p>For the interactive live stream view (<code>LiveStreamPage.tsx</code>):</p><ul><li>Multiple Node.js backend nodes run WebSocket servers (Socket.io).</li><li>Backend instances connect via a <strong>Redis Pub/Sub Adapter</strong>: when a viewer posts a comment on Server A, the message publishes to Redis channel <code>livestream:chef_marco</code>, broadcasting to all connected viewers across Servers B and C within 30 milliseconds.</li></ul><hr><h2 id="_6-what-breaks-first-at-scale" tabindex="-1">6. What Breaks First at Scale? <a class="header-anchor" href="#_6-what-breaks-first-at-scale" aria-label="Permalink to &quot;6. What Breaks First at Scale?&quot;">​</a></h2><ul><li><strong>At 10x</strong>: Direct playback of uncompressed 4K creator MP4 uploads freezes mobile browsers on slow cellular data.</li><li><strong>At 100x</strong>: Single WebSocket server instance memory exhaustion when 15,000 viewers join a celebrity chef&#39;s holiday live stream.</li><li><strong>At 1,000x</strong>: Egress bandwidth saturation without global CDN edge caching.</li></ul><hr><h2 id="_7-senior-engineer-improvements" tabindex="-1">7. Senior Engineer Improvements <a class="header-anchor" href="#_7-senior-engineer-improvements" aria-label="Permalink to &quot;7. Senior Engineer Improvements&quot;">​</a></h2><ol><li><strong>Adaptive Bitrate Transcoding</strong>: Use an automated FFmpeg worker to encode uploaded reels into an HLS <code>.m3u8</code> playlist with 480p, 720p, and 1080p stream tiers.</li><li><strong>Video Pre-Loading</strong>: In <code>ReelsFeed.tsx</code>, preload the <code>.m3u8</code> playlist header of the next two reels in the feed, enabling instantaneous zero-buffer swipe transitions.</li></ol><hr><h2 id="_8-spoken-interview-answer-30-seconds" tabindex="-1">8. Spoken Interview Answer (30 Seconds) <a class="header-anchor" href="#_8-spoken-interview-answer-30-seconds" aria-label="Permalink to &quot;8. Spoken Interview Answer (30 Seconds)&quot;">​</a></h2><p>&quot;For media delivery in Cooking Nexus, we decouple video streaming from real-time events. For video reels, we transcode MP4 uploads into multi-bitrate HLS streams distributed via AWS CloudFront, enabling instant playback and zero buffering across varying kitchen Wi-Fi signals. For interactive live masterclasses, we utilize WebSockets backed by a Redis Pub/Sub cluster, ensuring live viewer questions and recipe timestamps synchronize across all nodes with sub-50ms latency.&quot;</p>',16))])}const f=s(h,[["render",g]]);export{_ as __pageData,f as default};
